// The module loader (ARC-006): what is in modules/ becomes part of the harness.
//
//   node scripts/modules.mjs          write the generated files
//   node scripts/modules.mjs --check  fail if any is stale (runs in `npm run check`)
//
// From every modules/<name>/module.json, through the one reader in
// .claude/hooks/lib/modules.mjs, it writes two files that nobody edits by hand:
//
//   .claude-plugin/marketplace.json   every module that carries a
//                                     .claude-plugin/plugin.json, so Claude Code
//                                     loads its skills from inside the module,
//                                     namespaced <module>:<skill>
//   .claude/modules.md                the router rows the modules declare,
//                                     imported into CLAUDE.md so each row's
//                                     must-hold is loaded in every session even
//                                     when the skill itself never is
//
// And it checks the one thing it may not write: .claude/settings.json must know
// the marketplace and enable each module's plugin. Claude Code loads a plugin
// only once it is enabled there — tested 2026-09-27; a plugin.json that asks to
// be on by default is not enough — and the settings file is part of the locked
// safety core, so the line is added by hand and this names it exactly.

import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, posix } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readModules, manifestProblems, strayFolders } from '../../.claude/hooks/lib/modules.mjs';

const repoRoot = join(dirname(dirname(fileURLToPath(import.meta.url))), '..');
const check = process.argv.includes('--check');

export const MARKETPLACE = 'dear-modules';
const MARKETPLACE_PATH = join(repoRoot, '.claude-plugin', 'marketplace.json');
const ROUTER_PATH = join(repoRoot, '.claude', 'modules.md');
const SETTINGS_PATH = join(repoRoot, '.claude', 'settings.json');

const modules = readModules(repoRoot);
const findings = modules.flatMap(manifestProblems);
const plugins = modules.filter((m) => m.plugin);

const marketplace =
  JSON.stringify(
    {
      name: MARKETPLACE,
      description: 'The modules in modules/, generated by ux/scripts/modules.mjs. Do not edit by hand.',
      owner: { name: 'dear harness' },
      plugins: plugins.map((m) => ({
        name: m.name,
        source: `./${posix.join('modules', m.name)}`,
        description: m.plugin.description ?? '',
      })),
    },
    null,
    2,
  ) + '\n';

const rows = modules.flatMap((m) => m.router.map((r) => ({ ...r, module: m.name })));
const cell = (s) => String(s).replace(/\|/g, '\\|').replace(/\n/g, ' ');
const router =
  [
    '<!-- Generated by ux/scripts/modules.mjs from each modules/<name>/module.json. Do not edit by hand. -->',
    '',
    '**Rows from the modules.** Read with the table above; the last column holds',
    'even if the skill never loads.',
    '',
    '| She...                       | Skill                | Must hold regardless |',
    '| ---------------------------- | -------------------- | -------------------- |',
    ...rows.map((r) => `| ${cell(r.she)} | \`${cell(r.skill)}\` | ${cell(r.must)} |`),
  ].join('\n') + '\n';

function sync(path, content) {
  const current = existsSync(path) ? readFileSync(path, 'utf8').replace(/\r\n/g, '\n') : null;
  if (current === content) return;
  if (check) findings.push(`${posix.relative(repoRoot.replace(/\\/g, '/'), path.replace(/\\/g, '/'))} is stale: run \`npm run modules\``);
  else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
  }
}
sync(MARKETPLACE_PATH, marketplace);
sync(ROUTER_PATH, router);

const settings = existsSync(SETTINGS_PATH) ? JSON.parse(readFileSync(SETTINGS_PATH, 'utf8')) : {};
if (plugins.length && settings.extraKnownMarketplaces?.[MARKETPLACE]?.source?.path !== './') {
  findings.push(
    `.claude/settings.json does not know the module marketplace. Add under "extraKnownMarketplaces": "${MARKETPLACE}": { "source": { "source": "directory", "path": "./" } }`,
  );
}
for (const m of plugins) {
  if (settings.enabledPlugins?.[`${m.name}@${MARKETPLACE}`] !== true) {
    findings.push(`.claude/settings.json does not enable module ${m.name}. Add under "enabledPlugins": "${m.name}@${MARKETPLACE}": true`);
  }
}

// Views. The page code has to live under ux/app/, where Next.js finds routes,
// so VIEW_MODULE in ux/lib/views.js is the dashboard's copy of which route
// belongs to which module. It must say what the manifests say, both ways.
const viewsSource = readFileSync(join(repoRoot, 'ux', 'lib', 'views.js'), 'utf8');
const registered = Object.fromEntries(
  [...(/export const VIEW_MODULE = \{([^}]*)\}/.exec(viewsSource)?.[1] ?? '').matchAll(/'([^']+)':\s*'([^']+)'/g)].map((m) => [m[1], m[2]]),
);
const declared = Object.fromEntries(modules.flatMap((m) => Object.keys(m.views).map((route) => [route, m.name])));
for (const [route, name] of Object.entries(declared)) {
  if (registered[route] !== name) findings.push(`module ${name} declares view ${route}, but VIEW_MODULE in ux/lib/views.js does not map it to ${name}`);
}
for (const [route, name] of Object.entries(registered)) {
  if (declared[route] !== name && modules.some((m) => m.name === name)) findings.push(`VIEW_MODULE maps ${route} to ${name}, but ${name}'s module.json does not declare it`);
}

// A record folder no module owns, holding a file: left behind, or written back by a
// session on old code, after a module or its folder was renamed.
for (const record of ['data', 'data-sample', 'data-sandbox']) {
  for (const name of strayFolders(join(repoRoot, record), modules)) {
    findings.push(`${record}/${name}/ holds files but no module owns it: move them into the module's folder that should hold them, or into ${record}/archive/, and say so in ${record}/README.md`);
  }
}

if (findings.length) {
  console.error(`\n  MODULES CHECK FAILED\n\n${findings.map((f) => `  - ${f}`).join('\n')}\n\n  See ARC-006 and modules/README.md.\n`);
  process.exit(1);
}
console.log(`modules: ${modules.length} on file (${plugins.length} as plugins), ${rows.length} router row(s)${check ? ', generated files current' : ' written'}`);
